def load_inputs(workspace):
    data, hashes, sizes, cache = {}, {}, {}, {}
    for key, name in INPUT_FILES.items():
        path = (Path(workspace) / name).resolve()
        if path not in cache:
            raw = path.read_bytes()
            cache[path] = (json.loads(raw) if path.suffix == '.json' else raw.decode('utf8'), hashlib.sha256(raw).hexdigest(), len(raw))
        data[key], hashes[key], sizes[key] = cache[path]
    return data, hashes, sizes
